        "--partition-requested": "false",
        "--brainstorm-requested": "false",
        "--approve-requested": "false",
        "--skip-approve-requested": "false",
    }
    i = 0
    while i < len(args):
        token = args[i]
        if token in required or token in optional:
            if i + 1 >= len(args):
