    error_lines: list[str] = []
    route = ""
    brainstorm_prefix = "false"
    title_filter_reason = ""
    title_filter_marker = ""
    resume_step = ""
    session_id = ""
    run_id = ""
    brainstorm_done = ""
    marker_cleared = ""

    body = issue_body_file.read_text(encoding="utf-8", errors="replace")
