def _last_nonempty_line(lines: list[str]) -> tuple[int, str]:
    for idx in range(len(lines) - 1, -1, -1):
        if lines[idx].strip():
            return idx + 1, lines[idx]
    return 0, ""


def last_nonempty_line_number(path: str | Path) -> int:
