def _join_continuations(text: str) -> str:
    lines = text.split("\n")
    out: list[str] = []
    i = 0
    while i < len(lines):
        line = lines[i]
        while re.search(r"\\\s*$", line) and not re.search(r"\\\\\s*$", line):
            line = re.sub(r"\\\s*$", "", line)
            i += 1
            if i >= len(lines):
